{
  "name": "message-board",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "dev": "concurrently \"npm run server\" \"npm run client\"",
    "server": "node server/index.js",
    "client": "npm run dev --prefix client"
  },
  "dependencies": {
    "concurrently": "^8.2.2"
  }
}

import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
app.use(cors());
app.use(express.json());

let pglite;
const clients = [];

async function initDB() {
  // Ensure data directory exists
  const dataDir = path.join(__dirname, '..', 'data');
  fs.mkdirSync(dataDir, { recursive: true });

  pglite = await PGlite.create({
    dataDir: `file://${dataDir}`
  });

  await pglite.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      id SERIAL PRIMARY KEY,
      text TEXT NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
  `);

  console.log('Database initialized successfully');
}

// GET /api/messages - Fetch all messages for initial state
app.get('/api/messages', async (req, res) => {
  try {
    const result = await pglite.query(
      'SELECT id, text, created_at FROM messages ORDER BY created_at ASC'
    );
    res.json(result.rows);
  } catch (err) {
    console.error('Error fetching messages:', err);
    res.status(500).json({ error: 'Failed to fetch messages' });
  }
});

// POST /api/messages - Insert a new message and broadcast to SSE clients
app.post('/api/messages', async (req, res) => {
  try {
    const { text } = req.body;

    if (!text || typeof text !== 'string' || text.trim().length === 0) {
      return res.status(400).json({ error: 'Text is required and cannot be empty' });
    }

    const result = await pglite.query(
      'INSERT INTO messages (text) VALUES ($1) RETURNING id, text, created_at',
      [text.trim()]
    );

    const message = result.rows[0];

    // Broadcast new message to all active SSE clients
    const data = JSON.stringify(message);
    clients.forEach((client) => {
      client.res.write(`data: ${data}\n\n`);
    });

    res.json(message);
  } catch (err) {
    console.error('Error posting message:', err);
    res.status(500).json({ error: 'Failed to post message' });
  }
});

// GET /api/stream - SSE endpoint for real-time message updates
app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();

  // Add this client to the active connections list
  clients.push({ res });

  // Clean up when client disconnects
  req.on('close', () => {
    const index = clients.findIndex((c) => c.res === res);
    if (index !== -1) {
      clients.splice(index, 1);
    }
  });
});

async function start() {
  await initDB();
  app.listen(3000, () => {
    console.log('Server running on http://localhost:3000');
  });
}

start();

const API_BASE = 'http://localhost:3000';

const messageList = document.getElementById('message-list');
const messageForm = document.getElementById('message-form');
const messageInput = document.getElementById('message-input');
const connectionStatus = document.getElementById('connection-status');

// Format timestamp for display
function formatTime(timestamp) {
  const date = new Date(timestamp);
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

// Create and append a message element to the list
function appendMessage(msg) {
  const li = document.createElement('li');
  li.innerHTML = `
    <div class="message-text">${escapeHtml(msg.text)}</div>
    <div class="message-time">${formatTime(msg.created_at)}</div>
  `;
  messageList.appendChild(li);

  // Remove empty state if present
  const emptyState = messageList.querySelector('.empty-state');
  if (emptyState) {
    emptyState.remove();
  }

  // Scroll to bottom
  li.scrollIntoView({ behavior: 'smooth', block: 'end' });
}

// Escape HTML to prevent XSS
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// Fetch and render initial message history
async function loadMessages() {
  try {
    const response = await fetch(`${API_BASE}/api/messages`);
    if (!response.ok) throw new Error('Failed to fetch messages');

    const messages = await response.json();

    // Clear the list first
    messageList.innerHTML = '';

    if (messages.length === 0) {
      messageList.innerHTML = '<li class="empty-state">No messages yet. Be the first to post!</li>';
      return;
    }

    messages.forEach((msg) => appendMessage(msg));
  } catch (err) {
    console.error('Error loading messages:', err);
  }
}

// Connect to SSE stream for real-time updates
function connectToStream() {
  const eventSource = new EventSource(`${API_BASE}/api/stream`);

  eventSource.onopen = () => {
    connectionStatus.textContent = '● Connected';
    connectionStatus.className = 'status connected';
  };

  eventSource.onmessage = (event) => {
    try {
      const msg = JSON.parse(event.data);
      appendMessage(msg);
    } catch (err) {
      console.error('Error parsing SSE message:', err);
    }
  };

  eventSource.onerror = () => {
    connectionStatus.textContent = '● Disconnected';
    connectionStatus.className = 'status disconnected';
    eventSource.close();

    // Attempt to reconnect after a delay
    setTimeout(() => {
      console.log('Reconnecting...');
      connectToStream();
    }, 3000);
  };

  // Store reference for cleanup if needed
  window.eventSource = eventSource;
}

// Handle form submission to post a new message
messageForm.addEventListener('submit', async (e) => {
  e.preventDefault();

  const text = messageInput.value.trim();
  if (!text) return;

  try {
    const response = await fetch(`${API_BASE}/api/messages`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text }),
    });

    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || 'Failed to post message');
    }

    // Clear input after successful post
    messageInput.value = '';
    messageInput.focus();
  } catch (err) {
    console.error('Error posting message:', err);
    alert('Failed to post message: ' + err.message);
  }
});

// Initialize the application
loadMessages();
connectToStream();

