  e.preventDefault();
  const text = messageInput.value.trim();
  if (!text) return;

  await fetch('/api/messages', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text })
  });

  messageInput.value = '';
});

loadMessages();
